      hu: ["Katonai repülőgépek karbantartását végzi.", "Repülőgép-alkatrészeket gyárt."],
      ro: ["Întreține avioane militare.", "Produce componente aviatice."],
      en: ["Maintains military aircraft.", "Produces aviation components."]
